//! Checked-in echo SPIR-V (G1 first kernel): copies 1024 u32 in -> out.
//!
//! Source of truth is `echo.comp.spvasm` (human-readable assembly).
//! Regenerated by `zig build shaders` (spirv-as + spirv-val);
//! manual fallback:
//!
//!   spirv-as --target-env vulkan1.0 echo.comp.spvasm -o echo.comp.spv
//!   spirv-val --target-env vulkan1.0 echo.comp.spv
//!
//! and commit both files. The binary embeds here via `@embedFile`, so the
//! dispatched bytes are bit-for-bit the validated assembler output — no
//! hand transcription. `words` is the u32 view drivers consume (`pCode`).

const std = @import("std");

const bytes = @embedFile("echo.comp.spv");

pub const word_count: usize = bytes.len / 4;

comptime {
    if (bytes.len % 4 != 0) @compileError("echo.comp.spv size is not a whole word count");
}

/// Driver-ready u32 view (comptime-built from the embedded bytes).
pub const words: [word_count]u32 = blk: {
    var w: [word_count]u32 = undefined;
    for (0..word_count) |i| {
        w[i] = std.mem.readInt(u32, bytes[i * 4 ..][0..4], .little);
    }
    break :blk w;
};

/// Element count the shader copies (must match `%c1024` in the source).
pub const elem_count: usize = 1024;
pub const byte_size: usize = elem_count * 4;

test "echo spv header is Vulkan 1.0 with the expected bound" {
    try std.testing.expectEqual(@as(u32, 0x07230203), words[0]);
    try std.testing.expectEqual(@as(u32, 0x00010000), words[1]);
    try std.testing.expectEqual(@as(usize, 143), word_count);
    try std.testing.expectEqual(@as(u32, 22), words[3]);
}

test "echo spv walks as whole instructions" {
    // Structural walk: every instruction's word count lands exactly on the
    // next header and the stream ends on a boundary. Catches truncation or
    // accidental swaps of the checked-in binary.
    try std.testing.expectEqual(@as(u32, (2 << 16) | 17), words[5]); // OpCapability
    var i: usize = 5;
    var n_insn: usize = 0;
    while (i < word_count) {
        const w = words[i];
        const wc: usize = w >> 16;
        const op: usize = w & 0xffff;
        try std.testing.expect(wc >= 1);
        try std.testing.expect(op != 0);
        i += wc;
        n_insn += 1;
    }
    try std.testing.expectEqual(word_count, i);
    try std.testing.expectEqual(@as(usize, 36), n_insn);
}
